def match(orders):
    trades = []
    buy_book = []  # [(price, arrival_time, id, qty)]
    sell_book = []  # [(price, arrival_time, id, qty)]
    order_map = {}  # id -> (side, price, qty, arrival_time)
    order_in_book = {}  # id -> True if still in book
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_in_book and order_in_book[order_id]:
                order_in_book[order_id] = False
                # Remove from book
                side, price, qty, arr_time = order_map[order_id]
                if side == 'buy':
                    buy_book[:] = [(p, t, oid, q) for p, t, oid, q in buy_book if oid != order_id]
                else:
                    sell_book[:] = [(p, t, oid, q) for p, t, oid, q in sell_book if oid != order_id]

        elif order[0] == 'limit':
            order_type, order_id, side, price, qty = order
            order_map[order_id] = (side, price, qty, arrival_time)
            order_in_book[order_id] = True

            if side == 'buy':
                # Match against sell_book
                remaining_qty = qty
                matched_indices = []
                for i, (sell_price, sell_time, sell_id, sell_qty) in enumerate(sell_book):
                    if remaining_qty <= 0 or sell_price > price:
                        break

